{
  "status": "graded",
  "criteria": [
    {
      "criterion_id": "c1",
      "level_id": "met",
      "reason": "明确指出噪声下最大化会选到向上误差（高估动作）。",
      "evidence_quote": "When action-value estimates are noisy, maximizing them tends to select an upward error.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c2",
      "level_id": "met",
      "reason": "指出 Q-learning 目标中的后继动作最大值是选择偏差进入更新的位置。",
      "evidence_quote": "The successor-action maximum in the Q-learning target is where this selection enters the update.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c3",
      "level_id": "met",
      "reason": "说明即使动作价值相同，最大噪声实现也会被选中。",
      "evidence_quote": "Even equally valuable actions can show this effect because the largest noise realization wins.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c4",
      "level_id": "met",
      "reason": "列出 Q 值虚高、偏向坏动作和训练不稳定等后果。",
      "evidence_quote": "Inflated Q estimates can promote bad actions and unstable training.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c5",
      "level_id": "met",
      "reason": "正确描述 Double DQN 用在线网络选动作、目标网络评价。",
      "evidence_quote": "Double DQN selects the successor action with the online network and evaluates it using the target network.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c6",
      "level_id": "met",
      "reason": "指出延迟目标网络只减慢目标移动，不能消除选择偏差。",
      "evidence_quote": "A delayed target alone slows target movement but does not remove selection bias.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c7",
      "level_id": "met",
      "reason": "提到比较预测 Q 与经验回报，并检查动作集中异常。",
      "evidence_quote": "Compare predicted Q with empirical returns and inspect suspicious action concentration.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c8",
      "level_id": "met",
      "reason": "说明 Double DQN 缓解问题，但仍需探索、稳定优化和数据覆盖。",
      "evidence_quote": "Double DQN mitigates this issue; exploration, stable optimization and data coverage still matter.",
      "evidence_source": "text"
    }
  ]
}
